import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid webpage URL provided.")
    if not isinstance(database_name, str) or not database_name:
        raise ValueError("Invalid database name provided.")

    try:
        response = requests.get(webpage_url, timeout=10, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Error accessing the webpage: {e}") from e

    try:
        parsed_html = html.fromstring(response.content)
        table = parsed_html.xpath('//table')
        if not table:
            return 0
        table = table[0]
        headers = [th.text_content().strip() for th in table.xpath('.//th')]
        rows = []
        for row in table.xpath('.//tr'):
            cols = row.xpath('.//td')
            if cols:
                rows.append([col.text_content().strip() for col in cols])
        if not rows:
            return 0
        df = pd.DataFrame(rows, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error parsing the HTML content: {e}") from e

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        row_count = len(df)
        conn.close()
        return row_count
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Error writing to the database: {e}") from e

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, timeout=10, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Error accessing URL: {e}")

    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        rows = table.xpath('.//tr')
        if not rows:
            return 0

        headers = [th.text_content().strip() for th in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = [td.text_content().strip() for td in row.xpath('.//td')]
            if cols:
                data.append(cols)

        if not data:
            return 0

        df = pd.DataFrame(data, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error parsing HTML table: {e}")

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        row_count = len(df)
        conn.commit()
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return row_count

